using UnityEngine;

namespace Emberdelve.Net
{
    /// <summary>
    /// The network prefabs this build knows, as one small asset the code-created NetworkManager can load: NetBootstrap builds
    /// its NetworkManager from code (no scene NetworkManager, hence no DefaultNetworkPrefabs list), so prefabs are registered
    /// from here. Generated by EmberdelveNetBuilder at Assets/Emberdelve/Resources/Net/EmberdelveNetPrefabs.asset. Being under
    /// Resources and referencing the prefab is what carries the player prefab into a player build. Server and client load the
    /// same asset, so their prefab hashes match.
    /// </summary>
    public sealed class NetPrefabCatalog : ScriptableObject
    {
        /// <summary>Resources.Load path (no extension) of the generated asset.</summary>
        public const string ResourcePath = "Net/EmberdelveNetPrefabs";

        [SerializeField] private GameObject playerPrefab;

        /// <summary>The player prefab (NetworkObject + NetworkTransform + NetPlayerRig from the Modular Crypts scene rig).</summary>
        public GameObject PlayerPrefab => playerPrefab;

        /// <summary>Builder hook.</summary>
        public void SetPlayerPrefab(GameObject prefab) => playerPrefab = prefab;
    }
}
